//! OTLP trace messages generated by prost-build 0.14.6 from
//! [opentelemetry-proto](https://github.com/open-telemetry/opentelemetry-proto) v1.11.1
//! (`opentelemetry/proto/collector/trace/v1/trace_service.proto` and its imports).
//!
//! Checked in so builds need neither `build.rs` nor protoc. To regenerate, run prost-build
//! with `Config::new().out_dir(..).compile_protos(&[trace_service.proto], &[repo root])` and
//! copy `opentelemetry.proto.<package>.rs` to `<package with _>.rs` here.

#![allow(clippy::all, rustdoc::all)]

pub mod common {
    pub mod v1 {
        include!("common_v1.rs");
    }
}

pub mod resource {
    pub mod v1 {
        include!("resource_v1.rs");
    }
}

pub mod trace {
    pub mod v1 {
        include!("trace_v1.rs");
    }
}

pub mod collector {
    pub mod trace {
        pub mod v1 {
            include!("collector_trace_v1.rs");
        }
    }
}
